    <p>Ms. Ananya intends to register as a Registered Valuer for a specified asset class. She has a qualification in the relevant discipline and experience, and she has enrolled as a valuer member of a Registered Valuers Organisation (RVO). She is considering the educational course, valuation examination and registration application described in the ICAI chapter.</p>
